// Hand-written `koa-mount` stub for the flowatlas fixture suite.
//
// The point of this package, for a reader, is that it hands back middleware
// rather than an application: the prefix and the application are both inside the
// helper's own call, and `app.use(...)` therefore receives something that is not
// an application at all. That is what made outline's prefix invisible.

import type Application from 'koa';
import type { Middleware } from 'koa';

declare function mount(path: string, app: Application): Middleware;
declare function mount(app: Application): Middleware;

export default mount;
